svg.script:
(() => {
  const rider = document.getElementById("skater");
  const board = document.getElementById("board");
  const deck = document.getElementById("deck");
  const leftLeg = document.getElementById("leftLeg");
  const rightLeg = document.getElementById("rightLeg");
  const shoes = document.getElementById("shoes");
  const backArm = document.getElementById("backArm");
  const frontArm = document.getElementById("frontArm");

  const cx = 450, cy = 225, R = 260;

  // Idealized rider/board center of mass follows a smaller concentric arc.
  // No drag or pumping: mechanical energy is conserved on the transition.
  const rho = R - 48;
  const g = 720;       // SVG units per second squared
  const lipSpeed = 290;
  const flightTime = 2 * lipSpeed / g;

  // Integrate dt/dtheta = rho / speed(theta).
  // v² = v_lip² + 2 g rho cos(theta).
  const N = 1200;
  const angles = new Float64Array(N + 1);
  const times = new Float64Array(N + 1);
  const step = Math.PI / N;

  for (let i = 0; i <= N; i++) {
    angles[i] = -Math.PI / 2 + i * step;
    if (i) {
      const midpoint = angles[i] - step / 2;
      const speed = Math.sqrt(
        lipSpeed * lipSpeed + 2 * g * rho * Math.cos(midpoint)
      );
      times[i] = times[i - 1] + rho * step / speed;
    }
  }

  const rollTime = times[N];
  const period = 2 * (rollTime + flightTime);

  function angleAt(t) {
    let lo = 0, hi = N;
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1;
      if (times[mid] <= t) lo = mid;
      else hi = mid;
    }
    const f = (t - times[lo]) / (times[hi] - times[lo]);
    return angles[lo] + (angles[hi] - angles[lo]) * f;
  }

  const start = performance.now();

  function draw(now) {
    let t = ((now - start) / 1000 + rollTime / 2) % period;
    let theta, air = false, airTime = 0;

    if (t < rollTime) {
      theta = angleAt(t);
    } else if (t < rollTime + flightTime) {
      theta = Math.PI / 2;
      air = true;
      airTime = t - rollTime;
    } else if (t < 2 * rollTime + flightTime) {
      theta = angleAt(
        rollTime - (t - rollTime - flightTime)
      );
    } else {
      theta = -Math.PI / 2;
      air = true;
      airTime = t - 2 * rollTime - flightTime;
    }

    let x = cx + R * Math.sin(theta);
    let y = cy + R * Math.cos(theta);

    // Vertical lips give vertical launches:
    // horizontal position stays fixed, and gravity reverses vertical speed.
    if (air) y += -lipSpeed * airTime + 0.5 * g * airTime * airTime;

    rider.setAttribute(
      "transform",
      `translate(${x} ${y}) rotate(${-theta * 180 / Math.PI})`
    );

    const u = air ? airTime / flightTime : 0;
    const tuck = air ? Math.sin(Math.PI * u) ** 2 : 0;

    // Feet lift clear of the board; it makes one kickflip and is caught.
    // scaleY is the orthographic projection of rotation about deck length.
    const turn = air ? 2 * Math.PI * u : 0;
    const separation = 8 * tuck;
    board.setAttribute(
      "transform",
      `translate(0 ${-8 + separation})
       scale(1 ${Math.cos(turn)})
       translate(0 8)`
    );
    deck.setAttribute(
      "stroke",
      Math.cos(turn) < 0 ? "#53c8c6" : "#f47b71"
    );

    const lift = 14 * tuck;
    leftLeg.setAttribute(
      "d", `M-8 -48L${-22 - 7*tuck} ${-27 - 5*tuck}
            L-19 ${-11 - lift}`
    );
    rightLeg.setAttribute(
      "d", `M8 -48L${24 + 7*tuck} ${-30 - 5*tuck}
            L20 ${-11 - lift}`
    );
    shoes.setAttribute("transform", `translate(0 ${-lift})`);
    backArm.setAttribute(
      "d", `M-8 -69L-28 ${-53 - 13*tuck}L-39 ${-62 - 17*tuck}`
    );
    frontArm.setAttribute(
      "d", `M7 -70L27 ${-58 - 10*tuck}L38 ${-72 - 10*tuck}`
    );

    requestAnimationFrame(draw);
  }

  requestAnimationFrame(draw);
})();
